sys_variable_value.value:
(function execute(inputs, outputs) {
 
var data = inputs.objLucForEach;
var currentRecord = inputs.current_record;
var novoPayloadMRVSatualizado = JSON.parse(inputs.payloadMRVSatualizado);

function getMeasValidFrom(inicioVigencia, dataInicioCriacaoLuc) {
    function formatDate(date) {
        var day = date.getDate();
        var month = date.getMonth() + 1;
        var year = date.getFullYear();
        return year + '-' + (month < 10 ? '0' + month : month) + '-' + (day < 10 ? '0' + day : day);
    }
    if (inicioVigencia) {
        return formatDate(new Date(inicioVigencia));
    } else if (dataInicioCriacaoLuc) {
        return formatDate(new Date(dataInicioCriacaoLuc));
    } else {
        return 'não há';
    }
}

function getMeasurements(currentRecordFields, areaTotal) {
    var payload = { "Measurements": [], "Counters": [] };

      if (currentRecordFields.variables.u_desired_action_luc2.getValue() == 'unificacao') {
            payload.Measurements.push({
                "MeasType": "ZA03", //Área Bruta Locável
                "MeasValue": areaTotal.replace(/\./g, "").replace(",", ".") || 'não há', // Valor do tamanho do AC
                "MeasValidFrom": getMeasValidFrom(
                    currentRecordFields.variables.inicio_vigencia,
                    currentRecordFields.variables.data_de_inicio_de_criacao_da_luc
                ),
               // "MeasValidTo": "2040-12-31"
            });
            //payload.Counters.push({
              //  "NameCharacteristic": "Não há" // Relacionado ao MeasType "ZD06"
            //});
        }

        /* if (currentRecordFields.variables.do_you_have_crd_novo.getValue() == 'yes' || currentRecordFields.variables.do_you_have_crd_novo.getValue() == 'Yes') {
            payload.Measurements.push({
                "MeasType": "ZD01", //CRD
                "MeasValue": currentRecordFields.variables.crd_value_vs_novo.getDisplayValue() || 'não há', // Valor do tamanho do AC
                "MeasValidFrom": getMeasValidFrom(
                    currentRecordFields.variables.inicio_vigencia,
                    currentRecordFields.variables.data_de_inicio_de_criacao_da_luc
                ),
                //"MeasValidTo": "2040-12-31"
            });
            //payload.Counters.push({
              //  "NameCharacteristic": "Não há" // Relacionado ao MeasType "ZD06"
            //});
        }*/

    if (currentRecordFields.variables.measurements.getValue() == 'true') {
        if (currentRecordFields.variables.tr.getValue() == 'true') {
            payload.Measurements.push({
                "MeasType": "ZD06",
                "MeasValue": currentRecordFields.variables.tr_value.getDisplayValue().replace(/\./g, "").replace(",", ".") || 'não há',
                "MeasValidFrom": getMeasValidFrom(currentRecordFields.variables.inicio_vigencia, currentRecordFields.variables.change_start_date),
               // "MeasValidTo": "2040-12-31"
            });
        }
        if (currentRecordFields.variables.u_agua2 == 'Yes') {
            payload.Measurements.push({
                "MeasType": "ZF02",
                "MeasValue": areaTotal || 'não há',
                "MeasValidFrom": getMeasValidFrom(currentRecordFields.variables.inicio_vigencia, currentRecordFields.variables.change_start_date),
                //"MeasValidTo": "2040-12-31"
            });
            payload.Counters.push({ "NameCharacteristic": "Z_MEDIDOR_AGUA" });
        }
        if (currentRecordFields.variables.u_energia2 == 'Yes') {
            payload.Measurements.push({
                "MeasType": "ZF01",
                "MeasValue": areaTotal || 'não há',
                "MeasValidFrom": getMeasValidFrom(currentRecordFields.variables.inicio_vigencia, currentRecordFields.variables.change_start_date),
                //"MeasValidTo": "2040-12-31"
            });
            payload.Counters.push({ "NameCharacteristic": "Z_MEDIDOR_ENERGIA" });
        }
        if (currentRecordFields.variables.u_gas2 == 'Yes') {
            payload.Measurements.push({
                "MeasType": "ZD01",
                "MeasValue": areaTotal || 'não há',
                "MeasValidFrom": getMeasValidFrom(currentRecordFields.variables.inicio_vigencia, currentRecordFields.variables.change_start_date),
               // "MeasValidTo": "2040-12-31"
            });
            payload.Counters.push({ "NameCharacteristic": "Z_MEDIDOR_GAS" });
        }
    }
    return payload;
}

var finalPayloads = [];
data.forEach(function (item) {
    var areaTotalNova = item.areaAnterior_m || 'não há';
    var areaTotal = areaTotalNova.replace(/\./g, "").replace(",", ".");
    var lucAtual = item.lucAtual || 'não há';

    var measurements = getMeasurements(currentRecord, areaTotal);

    var catLoja = currentRecord.variables.luc_category.getValue();
    var catLojaResult = '';
    if (catLoja == 'store') catLojaResult = '1001';
    else if (catLoja == 'mall') catLojaResult = '1003';
    else if (catLoja == 'room') catLojaResult = '1008';
    else catLojaResult = 'Não há';

    var parteEdificio = novoPayloadMRVSatualizado[0].parte_do_edificio_luc;
    var mapping = {
        'area_padrao': '01',
        'taste_lab': '02',
        'praca': '03',
        'alameda': '04',
        'estacionamento': '05',
        'restaurante': '06'
    };
    var partBuildingResult = mapping[parteEdificio] || 'Não há';

    var grLucRdl = new GlideRecord('x_asscs_allos_informa_es_comerciais_rdl');
    grLucRdl.addEncodedQuery('sys_id=' + novoPayloadMRVSatualizado[0].luc_atual_atu);
    grLucRdl.query();
    var classTypeOfUseRdl = '';
    var salesResult = '';
    if (grLucRdl.next()) {
        classTypeOfUseRdl = grLucRdl.grupo_abl.toUpperCase().toString();

        var categorizacaoFinal = '';
if(classTypeOfUseRdl == 'SATELITE'){
    categorizacaoFinal = 'SATÉLITE';
}else if(classTypeOfUseRdl == 'MEGA-LOJA'){
    categorizacaoFinal = 'MEGA LOJA'
} else if(classTypeOfUseRdl == 'SEMI-ANCORA'){
    categorizacaoFinal = 'SEMI ÂNCORA'
} else if(classTypeOfUseRdl == 'ANCORA'){
    categorizacaoFinal = 'ÂNCORA'
} else {
    categorizacaoFinal = classTypeOfUseRdl;
}

        var salesRentable = grLucRdl.tipo_propriedade;
        salesResult = (salesRentable == 'PRÓPRIA') ? 'LOCA' : (salesRentable == 'VENDIDA') ? 'VEND' : 'Não encontrado';
    }

    var myObj = {
        "CompanyCode": currentRecord.variables.company_code.getDisplayValue(),
        "BusinessEntity": currentRecord.variables.shopping.u_unit_code.getDisplayValue(),
        "Luc": lucAtual,
        "LucType": "RU",
        "UsageType": catLojaResult,
        "LucText": lucAtual,
        "Building": '1',
        "ExistingULNo": lucAtual,
        "ClassTypeOfUse": categorizacaoFinal,
        "CPICompanyType": "CPI1",
        "CPIBudgetType": "CG",
        "AdditionalData": { "SaleRentable": salesResult },
        "Measurements": measurements.Measurements,
        "Counters": measurements.Counters
    };

    finalPayloads.push(myObj);
});

outputs.payloadbasic = finalPayloads[0];
outputs.payload2 = finalPayloads[1];
outputs.payloadobject = JSON.stringify(finalPayloads);

//gs.info('final PAYLOAD ' + finalPayloads);
gs.info('final PAYLOAD ' + JSON.stringify(finalPayloads));


})(inputs, outputs);

